// Package filestorage stores opaque binary objects (avatars, logos, attachments) under random keys.
// Callers never choose paths: keys are generated by NewKey and validated before touching the disk.
package filestorage

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"io"
	"time"
)

var (
	// ErrInvalidKey is returned for keys that are not generated by NewKey.
	ErrInvalidKey = errors.New("filestorage: invalid storage key")
	// ErrNotFound is returned when no object exists under the key.
	ErrNotFound = errors.New("filestorage: object not found")
)

// Info describes a stored object.
type Info struct {
	Size    int64
	ModTime time.Time
}

// Storage is the port for binary objects.
type Storage interface {
	// Save writes the content of r under key. It fails if the key already exists.
	Save(ctx context.Context, key string, r io.Reader) error
	// Open returns the object content. The caller closes the reader.
	Open(ctx context.Context, key string) (io.ReadCloser, error)
	// Delete removes the object. Deleting a missing object is not an error.
	Delete(ctx context.Context, key string) error
	// Stat returns the size and modification time, or ErrNotFound.
	Stat(ctx context.Context, key string) (Info, error)
}

// NewKey returns a new random key: 16 random bytes encoded as 32 lowercase hex characters.
func NewKey() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return hex.EncodeToString(b[:]), nil
}
